["Ward Warden II (Attohwa)"]={description="It is imperative that the pulse martello and the clone wards are kept in prime condition. This operation requires you to transport the necessary repair materials from the stockpile by way of pack chocobo. Be mindful of subjecting the bird to excess stress.",fame="Abyssea",fame_level="1",id=127,repeatable="Yes",reward="Varying amount of Cruor and Resistance Credits\n0~1 of: any Empyrean Armor +1 Head seals",start_npc="Resistance Sapper (Attohwa), Abyssea",start_zone="Attohwa"},
