["Water of Life"]={description="La Theine's water sources have been found to be contaminated! Miageau has entrusted you with vials of purification agent to cleanse each of the plateau's four ponds.",fame="Abyssea",fame_level="4",id=7,repeatable="Yes",reward="360 Cruor\nEvolith with random stats",start_npc="Miageau, Abyssea",start_pos="L-11",start_zone="La Theine"},
["Wayward Wares"]={description="A shipment of essential supplies intended for the Resistance outpost has been intercepted. Recover the scattered materials and deliver them to their intended destination.",fame="Abyssea",fame_level="1",id=39,reward="Based on how many [Key Item] returned:\nVarying amount of Cruor: 100~400\nVarying amount of Resistance Credits: 25~100",start_npc="Chapi Galepilai, Abyssea",start_pos="G-10",start_zone="Attohwa"},
["Weapons, Not Worries"]={description="A down-in-the-dumps artisan, seemingly too disheartened to take action herself, needs you to retrieve supplies for weaponcrafting. The hardened bone harvestable in the area should serve to raise her spirits.",fame="Abyssea",fame_level="1",id=21,repeatable="Yes",requirements={{count=1,id=605,name="Pickaxe"},{count=1,id=2639,name="Hardened Bone"}},reward="100 Cruor",start_npc="Peshi Yohnts, Abyssea",start_pos="F-9",start_zone="Tahrongi"},
["When Good Cardians Go Bad"]={description="Apururu's Cardians now guard each encampment, but word has it that not all of them are functioning optimally. Speak to the Cardians at each location and report back on any glitches you may have detected.",fame="Abyssea",fame_level="4",id=28,previous={"His Box, His Beloved"},repeatable="Yes",reward="First time completion:\n[Key Item] Viridian abyssite of guerdon\nSubsequent completions:\n400 Cruor",start_npc="Apururu, Abyssea",start_pos="H-12",start_zone="Tahrongi"},
["Whither the Whisker"]={description="A savage pack of fiends terrorizes Vunkerl, their whisker of power and omniscience confounding the bravest attempts of a celebrated San d'Orian hero to secure the safety of his men. It falls to you to sever and retrieve this Samsonian strand!",fame="Abyssea",fame_level="3",id=37,requirements={{count=1,id=3103,name="Black Whisker"}},reward="800 Cruor, [Key Item] Crimson abyssite of celerity",start_npc="Rahal, Abyssea",start_pos="F-4",start_zone="Vunkerl"},
}
